// producer.ts — shared by the order service
import { Kafka } from 'kafkajs';

const kafka = new Kafka({
  clientId: 'order-service',
  brokers: ['kafka-broker-1:9092', 'kafka-broker-2:9092'],
});

const producer = kafka.producer();

// order.created has 6 partitions; keying by order.id spreads orders across them
export async function publishOrderCreated(order: { id: string; customerEmail: string; items: { sku: string; qty: number }[] }): Promise<void> {
  await producer.connect();
  await producer.send({
    topic: 'order.created',
    messages: [
      {
        key: order.id,
        value: JSON.stringify(order),
      },
    ],
  });
}

