const kafka = new Kafka({
  clientId: 'inventory-service',
  brokers: ['kafka-broker-1:9092', 'kafka-broker-2:9092'],
});

const consumer = kafka.consumer({ groupId: 'order-processors' });

async function handleOrderCreated(order: { id: string; items: { sku: string; qty: number }[] }): Promise<void> {
  for (const item of order.items) {
    await decrementStock(item.sku, item.qty);
  }
  console.log(`[inventory] decremented stock for order ${order.id}`);
}

export async function startInventoryConsumer(): Promise<void> {
  await consumer.connect();
  await consumer.subscribe({ topic: 'order.created', fromBeginning: false });
  await consumer.run({
    eachMessage: async ({ message }) => {
      const order = JSON.parse(message.value!.toString());
      await handleOrderCreated(order);
    },
  });
}

