async function sendOrderEmail(order: { id: string; customerEmail: string }): Promise<void> {
  await emailClient.send({
    to: order.customerEmail,
    template: 'order-confirmation',
    data: { orderId: order.id },
  });
  console.log(`[notification] sent confirmation email for order ${order.id}`);
}

